#include "RefModel.h"
struct CallerContextGuard {
 VerilatedContext* caller;
 CallerContextGuard(): caller(Verilated::threadContextp()) {}
 ~CallerContextGuard(){ Verilated::threadContextp(caller); }
};
extern "C" void ref_model_eval(unsigned long long MTxClk,unsigned long long TxReset,unsigned long long TxUsedDataIn,unsigned long long TxUsedDataOut,unsigned long long TxDoneIn,unsigned long long TxAbortIn,unsigned long long TxStartFrmIn,unsigned long long TPauseRq,unsigned long long TxUsedDataOutDetected,unsigned long long TxFlow,unsigned long long DlyCrcEn,unsigned long long TxPauseTV,unsigned long long MAC,unsigned long long* ref_TxCtrlStartFrm,unsigned long long* ref_TxCtrlEndFrm,unsigned long long* ref_SendingCtrlFrm,unsigned long long* ref_CtrlMux,unsigned long long* ref_ControlData,unsigned long long* ref_WillSendControlFrame,unsigned long long* ref_BlockTxDone){CallerContextGuard restore_caller;static VerilatedContext context;static RefModel model(&context);Verilated::threadContextp(&context);model.MTxClk=MTxClk;model.TxReset=TxReset;model.TxUsedDataIn=TxUsedDataIn;model.TxUsedDataOut=TxUsedDataOut;model.TxDoneIn=TxDoneIn;model.TxAbortIn=TxAbortIn;model.TxStartFrmIn=TxStartFrmIn;model.TPauseRq=TPauseRq;model.TxUsedDataOutDetected=TxUsedDataOutDetected;model.TxFlow=TxFlow;model.DlyCrcEn=DlyCrcEn;model.TxPauseTV=TxPauseTV;model.MAC=MAC;model.eval();*ref_TxCtrlStartFrm=model.ref_TxCtrlStartFrm;*ref_TxCtrlEndFrm=model.ref_TxCtrlEndFrm;*ref_SendingCtrlFrm=model.ref_SendingCtrlFrm;*ref_CtrlMux=model.ref_CtrlMux;*ref_ControlData=model.ref_ControlData;*ref_WillSendControlFrame=model.ref_WillSendControlFrame;*ref_BlockTxDone=model.ref_BlockTxDone;}
